  border-radius: 12px;
  background: var(--card);
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.45;
}

.sales-report__header {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.sales-report__title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.sales-report__hint {
  margin: 0;
  font-size: 12px;
  opacity: 0.7;
}

.sales-report__status {
  margin: 0;
  font-size: 12px;
}

.sales-report__scroll {
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
}

.sales-report__table {
  width: 100%;
  border-collapse: collapse;
  table-layout: auto;
}

.sales-report__table th,
.sales-report__table td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  text-align: left;
  vertical-align: middle;
}

.sales-report__table thead th {
  font-weight: 600;
  white-space: nowrap;
}

.sales-report__col-revenue {
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.sales-report__col-month {
  white-space: nowrap;
}

.sales-report__sort {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.sales-report__sort:hover {
  text-decoration: underline;
}

.sales-report__sort:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
  border-radius: 4px;
}

.sales-report__sort-icon {
  opacity: 0.7;
}

.sales-report__row {
  cursor: pointer;
}

.sales-report__row:hover {
  background: var(--muted);
}

.sales-report__row:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}

.sales-report__row[data-selected="true"] {
  background: var(--muted);
}

.sales-report__detail td {
  border-bottom: 1px solid var(--border);
  background: var(--background);
}

.sales-report__detail-inner {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
}

.sales-report__detail-month {
  font-weight: 600;
}

.sales-report__detail-label {
  font-size: 12px;
  opacity: 0.7;
}

.sales-report__detail-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

